/** Two cells touch on a side or corner when neither coordinate differs by more than 1. */
const areTouching = ([ax, ay]: Cell, [bx, by]: Cell): boolean =>
  Math.abs(ax - bx) <= 1 && Math.abs(ay - by) <= 1;

/** Two cells are neighbours when they touch — a cell is not its own neighbour. */
const areNeighbours = (a: Cell, b: Cell): boolean =>
  areTouching(a, b) && !isSameCell(a, b);

const countLiveNeighbours = (cell: Cell, liveCells: Cell[]): number =>
  liveCells.filter((candidate) => areNeighbours(candidate, cell)).length;
